107	/// Check limit <= indexes->size() and call column.indexImpl(const PaddedPodArray<Type> & indexes, UInt64 limit).
108	template <typename Column>
109	ColumnPtr selectIndexImpl(const Column & column, const IColumn & indexes, size_t limit)
110	{
111	    if (limit == 0)
112	        limit = indexes.size();
113	
114	    if (indexes.size() < limit)
115	        throw Exception(ErrorCodes::SIZES_OF_COLUMNS_DOESNT_MATCH,
116	            "Size of indexes ({}) is less than required ({})", indexes.size(), limit);
117	
118	    if (const auto * data_uint8 = detail::getIndexesData<UInt8>(indexes))
119	        return column.template indexImpl<UInt8>(*data_uint8, limit);
120	    else if (const auto * data_uint16 = detail::getIndexesData<UInt16>(indexes))
121	        return column.template indexImpl<UInt16>(*data_uint16, limit);
122	    else if (const auto * data_uint32 = detail::getIndexesData<UInt32>(indexes))
123	        return column.template indexImpl<UInt32>(*data_uint32, limit);
124	    else if (const auto * data_uint64 = detail::getIndexesData<UInt64>(indexes))
125	        return column.template indexImpl<UInt64>(*data_uint64, limit);
126	    else
127	        throw Exception("Indexes column for IColumn::select must be ColumnUInt, got " + indexes.getName(),
128	                        ErrorCodes::LOGICAL_ERROR);
129	}
